#include <bits/stdc++.h>
using namespace std;
class Solution {public:vector<int> minOperationsQueries(int n,vector<vector<int>>& edges,vector<vector<int>>& queries){int LOG=1;while((1<<LOG)<=n)++LOG;vector<vector<pair<int,int>>> g(n);for(auto&e:edges){g[e[0]].push_back({e[1],e[2]});g[e[1]].push_back({e[0],e[2]});}vector<vector<int>> up(LOG,vector<int>(n)),cnt(n,vector<int>(27));vector<int> depth(n),par(n,-1),order={0};par[0]=0;for(int i=0;i<(int)order.size();++i){int u=order[i];for(auto [v,w]:g[u])if(v!=par[u]){par[v]=u;depth[v]=depth[u]+1;cnt[v]=cnt[u];++cnt[v][w];order.push_back(v);}}up[0]=par;for(int b=1;b<LOG;++b)for(int i=0;i<n;++i)up[b][i]=up[b-1][up[b-1][i]];vector<int> ans;for(auto&q:queries){int a=q[0],b=q[1],x=a,y=b;if(depth[x]<depth[y])swap(x,y);int diff=depth[x]-depth[y];for(int j=0;j<LOG;++j)if((diff>>j)&1)x=up[j][x];if(x!=y){for(int j=LOG-1;j>=0;--j)if(up[j][x]!=up[j][y]){x=up[j][x];y=up[j][y];}x=up[0][x];}int len=depth[a]+depth[b]-2*depth[x],best=0;for(int w=1;w<=26;++w)best=max(best,cnt[a][w]+cnt[b][w]-2*cnt[x][w]);ans.push_back(len-best);}return ans;}};
